/* ============ A Little Better — palette & base ============ */
:root {
  --bg: #faf6ef;
  --bg-soft: #f3ecdf;
  --card: #fffdf8;
  --ink: #26231e;
  --ink-soft: #5c564a;
  --ink-faint: #8a8271;
  --line: #e3dac7;
  --accent: #c0562f;
  --accent-ink: #9b3f1f;
  --accent-soft: #f4decf;
  --good: #4e7a54;
  --good-soft: #e2ece0;
  --warn: #b07c26;
  --warn-soft: #f5ecd6;
  --bad: #b3452f;
  --bad-soft: #f6dfd9;
  --focus: #4a6ea8;
  --serif: "Iowan Old Style", "Palatino Linotype", Palatino, "Book Antiqua", Georgia, serif;
  --sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --radius: 14px;
  --shadow: 0 1px 2px rgba(38, 35, 30, .05), 0 8px 30px rgba(38, 35, 30, .07);
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #1c1a16;
    --bg-soft: #23201b;
    --card: #26231d;
    --ink: #ece5d6;
    --ink-soft: #b6ad9b;
    --ink-faint: #8b8372;
    --line: #3a362d;
    --accent: #e07b50;
    --accent-ink: #f0a07c;
    --accent-soft: #3b2a20;
    --good: #8db58a;
    --good-soft: #26301f;
    --warn: #d8ab59;
    --warn-soft: #38301f;
    --bad: #e08a72;
    --bad-soft: #3a2420;
    --focus: #8fb0e8;
    --shadow: 0 1px 2px rgba(0,0,0,.3), 0 8px 30px rgba(0,0,0,.35);
  }
}

* { box-sizing: border-box; }

html { scroll-behavior: smooth; }

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *, *::before, *::after { animation: none !important; transition: none !important; }
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--sans);
  font-size: 17px;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

.wrap { max-width: 1080px; margin: 0 auto; padding: 0 24px; }

.visually-hidden {
  position: absolute !important;
  width: 1px; height: 1px;
  margin: -1px; padding: 0; overflow: hidden;
  clip: rect(0 0 0 0); clip-path: inset(50%);
  white-space: nowrap; border: 0;
}

.skip-link {
  position: absolute; left: 8px; top: -60px;
  background: var(--ink); color: var(--bg);
  padding: 8px 14px; border-radius: 8px; z-index: 100;
  transition: top .15s;
}
.skip-link:focus { top: 8px; }

:focus-visible { outline: 3px solid var(--focus); outline-offset: 2px; border-radius: 4px; }

/* ============ Header ============ */
.site-head { border-bottom: 1px solid var(--line); background: var(--bg-soft); }
.site-head .wrap { display: flex; align-items: center; gap: 18px; padding-top: 18px; padding-bottom: 16px; flex-wrap: wrap; }
.brand { display: flex; align-items: center; gap: 10px; }
.brand-mark { display: grid; place-items: center; color: var(--accent); }
.brand-name { font-family: var(--serif); font-weight: 600; font-size: 1.15rem; letter-spacing: .01em; }
.tagline { margin: 0; color: var(--ink-soft); font-size: .92rem; font-style: italic; }

/* ============ Hero ============ */
.hero { padding: 56px 0 44px; }
.hero h1 {
  font-family: var(--serif);
  font-size: clamp(2rem, 5vw, 3.2rem);
  font-weight: 600; letter-spacing: -.01em;
  line-height: 1.12; margin: 0 0 20px; max-width: 16ch;
}
.hero h1 em { font-style: normal; color: var(--accent); }
.hero .lead { font-size: 1.12rem; color: var(--ink-soft); max-width: 62ch; margin: 0 0 28px; }
.hero-actions { display: flex; gap: 12px; flex-wrap: wrap; }

/* ============ Buttons ============ */
.btn {
  font: inherit; font-weight: 600;
  border-radius: 10px; padding: 11px 20px; cursor: pointer;
  border: 1.5px solid transparent;
  transition: transform .1s, background .15s, box-shadow .15s, color .15s, border-color .15s;
  text-decoration: none;
  display: inline-flex; align-items: center; gap: 6px;
}
.btn:active { transform: translateY(1px); }
.btn-primary { background: var(--accent); color: #fff; box-shadow: var(--shadow); }
.btn-primary:hover { background: var(--accent-ink); }
.btn-ghost { background: transparent; color: var(--ink); border-color: var(--line); }
.btn-ghost:hover { border-color: var(--accent); color: var(--accent); }
.btn-sm { padding: 8px 14px; font-size: .9rem; }
.btn[disabled] { opacity: .45; cursor: not-allowed; box-shadow: none; }

/* ============ Tabs ============ */
.tabs { position: sticky; top: 0; z-index: 50; background: var(--bg-soft); border-bottom: 1px solid var(--line); backdrop-filter: blur(6px); }
.tab-list { display: flex; gap: 4px; overflow-x: auto; padding-top: 8px; padding-bottom: 8px; }
.tab {
  font: inherit; font-weight: 500; color: var(--ink-soft);
  background: transparent; border: none; border-radius: 999px;
  padding: 8px 16px; cursor: pointer; white-space: nowrap;
  display: inline-flex; align-items: center; gap: 7px;
}
.tab:hover { color: var(--ink); background: var(--card); }
.tab[aria-selected="true"], .tab.is-active { color: var(--ink); background: var(--card); box-shadow: var(--shadow); }
.tab-icon { font-size: 1.05em; line-height: 1; }

/* ============ Panels ============ */
main { padding: 40px 0 80px; }
.panel { animation: fadein .35s ease; }
@keyframes fadein { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: none; } }
.panel-intro { max-width: 66ch; margin-bottom: 28px; }
.panel-intro h2 { font-family: var(--serif); font-size: 1.9rem; margin: 0 0 8px; }
.panel-intro p { color: var(--ink-soft); margin: 0; }

.hint { color: var(--ink-faint); font-size: .92rem; margin: 6px 0 14px; }

/* ============ Editor / metrics ============ */
.clarity-grid { display: grid; grid-template-columns: 1fr 300px; gap: 24px; align-items: start; }
.kind-grid { display: grid; grid-template-columns: 1fr 340px; gap: 24px; align-items: start; }

.editor-card {
  background: var(--card); border: 1px solid var(--line); border-radius: var(--radius);
  box-shadow: var(--shadow); padding: 16px;
}
textarea, input[type="text"], input[type="number"], select {
  font: inherit; color: var(--ink); background: var(--bg);
  border: 1px solid var(--line); border-radius: 10px; padding: 12px 14px;
  width: 100%;
}
textarea { resize: vertical; min-height: 120px; line-height: 1.55; }
textarea:focus, input:focus, select:focus { border-color: var(--accent); outline: none; box-shadow: 0 0 0 3px var(--accent-soft); }
textarea::placeholder { color: var(--ink-faint); }
.editor-toolbar { display: flex; gap: 8px; flex-wrap: wrap; margin-top: 12px; }

.metrics { position: sticky; top: 84px; display: grid; gap: 16px; }
.gauge {
  background: var(--card); border: 1px solid var(--line); border-radius: var(--radius);
  box-shadow: var(--shadow); padding: 20px; text-align: center;
}
.gauge-ring {
  --pct: 0;
  width: 150px; height: 150px; margin: 0 auto 12px; position: relative;
  border-radius: 50%;
  background: conic-gradient(var(--accent) calc(var(--pct) * 1%), var(--line) 0);
  display: grid; place-items: center;
  transition: background .3s;
}
.gauge-ring::after {
  content: ""; position: absolute; inset: 12px; border-radius: 50%;
  background: var(--card);
}
.gauge-value { position: relative; z-index: 1; line-height: 1.05; }
.gauge-value #grade-num { font-family: var(--serif); font-size: 2.4rem; font-weight: 600; }
.gauge-unit { display: block; font-size: .8rem; color: var(--ink-faint); text-transform: uppercase; letter-spacing: .08em; }
.gauge-label { margin: 4px 10px 0; font-size: .9rem; color: var(--ink-soft); }
.gauge-ring.easy  { background: conic-gradient(var(--good) calc(var(--pct) * 1%), var(--line) 0); }
.gauge-ring.hard  { background: conic-gradient(var(--bad)  calc(var(--pct) * 1%), var(--line) 0); }

.metric-list {
  background: var(--card); border: 1px solid var(--line); border-radius: var(--radius);
  box-shadow: var(--shadow); margin: 0; padding: 6px 0;
}
.metric { display: flex; justify-content: space-between; padding: 10px 18px; border-bottom: 1px solid var(--line); }
.metric:last-child { border-bottom: none; }
.metric dt { color: var(--ink-soft); }
.metric dd { margin: 0; font-weight: 600; font-variant-numeric: tabular-nums; }

/* Insights */
.insights { margin-top: 24px; }
.insights ul { list-style: none; margin: 0; padding: 0; display: grid; gap: 10px; }
.insight {
  background: var(--card); border: 1px solid var(--line); border-left: 4px solid var(--warn);
  border-radius: 8px; padding: 12px 16px; font-size: .95rem;
}
.insight.good { border-left-color: var(--good); }
.insight.ok   { border-left-color: var(--warn); }
.insight.hard { border-left-color: var(--bad); }
.insight strong { display: block; font-size: .82rem; text-transform: uppercase; letter-spacing: .07em; color: var(--ink-faint); margin-bottom: 2px; }

/* ============ Compass ============ */
.compass { max-width: 760px; }
.steps-progress { list-style: none; display: flex; gap: 6px; padding: 0; margin: 0 0 24px; }
.steps-progress li { flex: 1; height: 6px; border-radius: 3px; background: var(--line); }
.steps-progress li.done { background: var(--accent); }
.steps-progress li.current { background: var(--accent); opacity: .5; }

.step { background: var(--card); border: 1px solid var(--line); border-radius: var(--radius); box-shadow: var(--shadow); padding: 26px; animation: fadein .3s ease; }
.step h3 { font-family: var(--serif); font-size: 1.4rem; margin: 0 0 6px; }
.step-kicker { display: block; font-family: var(--sans); font-size: .78rem; font-weight: 700; text-transform: uppercase; letter-spacing: .1em; color: var(--accent); margin-bottom: 6px; }
.field-label { display: block; font-weight: 600; margin: 18px 0 6px; font-size: .98rem; }
.step textarea { background: var(--bg); }

.option-list, .weigh-list { display: grid; gap: 10px; margin: 12px 0; }
.option-row { display: flex; gap: 8px; align-items: center; }
.option-row input { background: var(--bg); }
.option-row .remove, .weigh-item .remove {
  background: transparent; border: none; color: var(--ink-faint); font-size: 1.2rem;
  cursor: pointer; padding: 6px 10px; border-radius: 8px; line-height: 1;
}
.option-row .remove:hover, .weigh-item .remove:hover { color: var(--bad); background: var(--bad-soft); }

.weigh-item { border: 1px solid var(--line); border-radius: 10px; padding: 14px; background: var(--bg); }
.weigh-item h4 { margin: 0 0 10px; font-family: var(--serif); font-size: 1.05rem; }
.weigh-pair { margin-bottom: 10px; }
.weigh-pair label { display: block; font-size: .85rem; color: var(--ink-soft); margin-bottom: 3px; }

.summary-box {
  background: var(--bg); border: 1px solid var(--line); border-radius: 10px; padding: 20px;
  font-family: var(--serif); font-size: 1.02rem; line-height: 1.6; margin: 8px 0 16px; white-space: pre-wrap;
}
.summary-actions { display: flex; gap: 10px; }
.copied-note { color: var(--good); font-weight: 600; min-height: 1.4em; margin: 10px 0 0; }

.step-nav { display: flex; justify-content: space-between; margin-top: 20px; }

/* ============ Kind speech ============ */
.lens-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 12px; }
.lens {
  background: var(--card); border: 1px solid var(--line); border-radius: var(--radius);
  box-shadow: var(--shadow); padding: 16px 18px;
}
.lens h3 { margin: 0 0 4px; font-size: 1rem; display: flex; gap: 8px; align-items: center; }
.lens .verdict { font-weight: 700; font-size: .86rem; text-transform: uppercase; letter-spacing: .06em; }
.lens.kind .verdict { color: var(--good); }
.lens.warn .verdict { color: var(--warn); }
.lens.hurt .verdict { color: var(--bad); }
.lens p { margin: 6px 0 0; font-size: .93rem; color: var(--ink-soft); }
.lens.light-up { border-color: var(--good); background: var(--good-soft); }

/* ============ Ripple ============ */
.ripple-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 28px; align-items: start; }
.ripple-form { background: var(--card); border: 1px solid var(--line); border-radius: var(--radius); box-shadow: var(--shadow); padding: 24px; }
.custom-row { display: flex; gap: 8px; margin-top: 6px; }
.custom-row input[type="number"] { width: 90px; }
.range-row { display: flex; align-items: center; gap: 14px; margin-top: 6px; }
input[type="range"] { flex: 1; accent-color: var(--accent); }
.range-row output { font-weight: 600; font-variant-numeric: tabular-nums; min-width: 72px; text-align: right; }
.ripple-result { font-family: var(--serif); font-size: 1.25rem; margin: 22px 0 0; line-height: 1.5; }
.ripple-result .num { color: var(--accent); font-weight: 700; }

.ripple-viz { background: var(--card); border: 1px solid var(--line); border-radius: var(--radius); box-shadow: var(--shadow); padding: 20px; }
.ripple-viz svg { width: 100%; height: auto; display: block; }
.viz-caption { text-align: center; margin: 10px 0 0; color: var(--ink-soft); }

.today-card { margin-top: 28px; background: var(--accent-soft); border: 1px solid var(--line); border-radius: var(--radius); padding: 22px 24px; display: flex; align-items: center; gap: 16px; flex-wrap: wrap; }
.today-card h3 { margin: 0; font-family: var(--serif); font-size: 1.1rem; }
.today-card .today-act { margin: 0; font-size: 1.05rem; }
.today-card .btn { margin-left: auto; }

/* ============ Why ============ */
.why-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: 18px; }
.why-card { background: var(--card); border: 1px solid var(--line); border-radius: var(--radius); box-shadow: var(--shadow); padding: 22px; }
.why-card h3 { margin: 0 0 8px; font-family: var(--serif); font-size: 1.15rem; display: flex; gap: 8px; align-items: center; }
.why-card p { margin: 0; color: var(--ink-soft); font-size: .96rem; }
.epigraph { margin: 44px auto 0; max-width: 52ch; text-align: center; border: none; }
.epigraph p { font-family: var(--serif); font-style: italic; font-size: 1.25rem; color: var(--ink-soft); margin: 0 0 8px; }
.epigraph footer { color: var(--ink-faint); font-size: .9rem; }

/* ============ Footer ============ */
.site-foot { border-top: 1px solid var(--line); background: var(--bg-soft); padding: 22px 0; }
.site-foot p { margin: 0; color: var(--ink-soft); font-size: .92rem; text-align: center; }

/* ============ Responsive ============ */
@media (max-width: 820px) {
  .clarity-grid, .kind-grid, .ripple-grid { grid-template-columns: 1fr; }
  .metrics { position: static; grid-template-columns: 1fr 1fr; }
  .gauge { grid-row: span 2; display: grid; place-items: center; }
  .hero { padding: 40px 0 32px; }
}
@media (max-width: 480px) {
  .metrics { grid-template-columns: 1fr; }
  .gauge { grid-row: auto; }
}

/* A Little Better — plain words, careful decisions, kind speech, compounding kindness. */

/* ============================================================
   Tabs
   ============================================================ */
const tabs = Array.from(document.querySelectorAll(".tab"));
const panels = Array.from(document.querySelectorAll(".panel"));

function activatePanel(name) {
  tabs.forEach((t) => {
    const on = t.dataset.panel === name;
    t.setAttribute("aria-selected", String(on));
    t.classList.toggle("is-active", on);
  });
  panels.forEach((p) => {
    const on = p.id === "panel-" + name;
    p.hidden = !on;
    p.classList.toggle("is-active", on);
  });
}

tabs.forEach((t) =>
  t.addEventListener("click", () => {
    activatePanel(t.dataset.panel);
    try { history.replaceState(null, "", "#" + t.dataset.panel); } catch (_) {}
    t.focus();
  })
);

/* keyboard: left/right arrows move between tabs */
tabs.forEach((t, i) =>
  t.addEventListener("keydown", (e) => {
    let n = null;
    if (e.key === "ArrowRight") n = (i + 1) % tabs.length;
    if (e.key === "ArrowLeft") n = (i - 1 + tabs.length) % tabs.length;
    if (e.key === "Home") n = 0;
    if (e.key === "End") n = tabs.length - 1;
    if (n !== null) {
      e.preventDefault();
      tabs[n].focus();
      tabs[n].click();
    }
  })
);

/* deep-link on load */
const startPanel = (location.hash || "").replace("#", "");
if (tabs.some((t) => t.dataset.panel === startPanel)) activatePanel(startPanel);

/* ============================================================
   Plain Words — readability analysis
   ============================================================ */

