import puppeteer from "puppeteer-core";
import { createServer } from "node:http";
import { readFile } from "node:fs/promises";
import { extname, join } from "node:path";
const root=process.cwd();const mime={".html":"text/html",".css":"text/css",".js":"text/javascript"};
const server=createServer(async(req,res)=>{try{let p=req.url.split("?")[0];if(p==="/")p="/index.html";const d=await readFile(join(root,p));res.writeHead(200,{"content-type":mime[extname(p)]||"application/octet-stream"});res.end(d);}catch{res.writeHead(404);res.end("nf");}});
await new Promise(r=>server.listen(0,r));const port=server.address().port;
const browser=await puppeteer.launch({executablePath:"/Applications/Google Chrome.app/Contents/MacOS/Google Chrome",headless:"new",args:["--no-sandbox"]});
const page=await browser.newPage();
await page.setViewport({width:1280,height:900,deviceScaleFactor:2});
const bad=[];
page.on("pageerror",e=>bad.push("pageerror:"+e.message));
page.on("response",r=>{if(r.status()>=400)bad.push(r.status()+" "+r.url());});
await page.goto("http://127.0.0.1:"+port+"/",{waitUntil:"networkidle0"});

// each tab opens
for (const t of ["clarity","compass","kindspeech","ripple","why"]) {
  await page.click("#tab-"+t);
  const visible = await page.$eval("#panel-"+t, e=>!e.hidden);
  if(!visible) bad.push("panel "+t+" not visible");
}

// keyboard nav: arrow right moves tab
await page.click("#tab-clarity");
await page.keyboard.press("ArrowRight");
const sel = await page.$$eval(".tab", ts=>ts.find(t=>t.getAttribute("aria-selected")==="true").id);
if(sel!=="tab-compass") bad.push("keyboard nav broken: "+sel);

// simplify flow
await page.click("#tab-clarity");
await page.click("#btn-sample");
await page.click("#btn-simplify");
const gradeAfter = await page.$eval("#grade-num", e=>e.textContent);

// screenshot set
const shots = ["final-home","final-clarity","final-compass","final-kind","final-ripple","final-why"];
for (const [i,t] of ["clarity","compass","kindspeech","ripple","why"].entries()) {
  await page.click("#tab-"+t);
  await new Promise(r=>setTimeout(r,250));
  await page.screenshot({path: shots[i]+".jpg", type:"jpeg", quality:70});
}
await page.click("#tab-clarity");
await page.screenshot({path:"final-home.jpg", type:"jpeg", quality:70});

console.log(JSON.stringify({bad, gradeAfter, sel}, null, 2));
await browser.close(); server.close();
EOF
